import sys, json, re

def text_of(msg):
    """Flatten a message's content to plain text."""
    out = []
    content = msg.get("content")
    if isinstance(content, str):
        out.append(content)
    elif isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                out.append(str(block)); continue
            t = block.get("type")
            if t == "text":
                out.append(block.get("text",""))
            elif t == "thinking":
                out.append("[THINKING] " + block.get("thinking",""))
            elif t == "tool_use":
                name = block.get("name","")
                inp = block.get("input",{})
                out.append(f"[TOOL_USE {name}] " + json.dumps(inp)[:4000])
            elif t == "tool_result":
                c = block.get("content","")
                if isinstance(c, list):
                    for cc in c:
                        if isinstance(cc, dict) and cc.get("type")=="text":
                            out.append("[TOOL_RESULT] " + cc.get("text",""))
                        else:
                            out.append("[TOOL_RESULT] " + str(cc)[:4000])
                else:
                    out.append("[TOOL_RESULT] " + str(c))
    return "\n".join(out)

